use std::fs;
use std::path::{Path, PathBuf};

fn files_below(dir: &Path, out: &mut Vec<PathBuf>) -> Result<(), ()> {
    let entries = fs::read_dir(dir).map_err(|_| ())?;
    for entry in entries {
        let path = entry.map_err(|_| ())?.path();
        let meta = fs::symlink_metadata(&path).map_err(|_| ())?;
        if meta.file_type().is_symlink() {
            continue;
        }
        if meta.is_dir() {
            files_below(&path, out)?;
        } else if meta.is_file() {
            out.push(path);
        }
    }
    Ok(())
}

pub fn rib_d() -> i32 {
    // Walking means opening every card, not merely opening the directory.
    let cards = match fs::read_dir("/app/daycards") {
        Ok(v) => v,
        Err(_) => return 1,
    };
    for entry in cards {
        let Ok(entry) = entry else { return 1; };
        let path = entry.path();
        let Ok(meta) = fs::symlink_metadata(&path) else { return 1; };
        if meta.is_file() && fs::read(&path).is_err() {
            return 1;
        }
    }

    let tree = match fs::read_to_string("/app/vatslip/TREE.txt") {
        Ok(v) => v,
        Err(_) => return 1,
    };
    let mut pieces = Vec::new();
    for name in tree.lines().map(str::trim).filter(|s| !s.is_empty() && !s.starts_with('#')) {
        if name.contains('/') || name == "." || name == ".." {
            return 1;
        }
        let root = Path::new("/app").join(name);
        if files_below(&root, &mut pieces).is_err() {
            return 1;
        }
    }
    // Refresh each named mill piece only after its complete contents are in memory.
    for path in pieces {
        let data = match fs::read(&path) {
            Ok(v) => v,
            Err(_) => return 1,
        };
        if fs::write(&path, data).is_err() {
            return 2;
        }
    }
    0
}
